package com.forgeci.domain.repository;
import com.forgeci.domain.user.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="github_connections",schema="forgeci",uniqueConstraints=@UniqueConstraint(name="uk_github_connection_user",columnNames="user_id"))
public class GitHubConnection { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="github_user_id",nullable=false,length=120) private String githubUserId; @Column(name="github_login",nullable=false,length=120) private String githubLogin; @Column(name="access_token_ciphertext",nullable=false,length=2000) private String accessTokenCiphertext; @Column(name="connected_at",nullable=false,updatable=false) private Instant connectedAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(nullable=false) private boolean active=true; protected GitHubConnection(){} public GitHubConnection(User u,String uid,String login,String ciphertext){user=u;githubUserId=uid;githubLogin=login;accessTokenCiphertext=ciphertext;} @PrePersist void create(){var n=Instant.now();connectedAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public User getUser(){return user;} public String getGithubUserId(){return githubUserId;} public String getGithubLogin(){return githubLogin;} public boolean isActive(){return active;} public void replaceToken(String uid,String login,String ciphertext){githubUserId=uid;githubLogin=login;accessTokenCiphertext=ciphertext;active=true;} public void disconnect(){active=false;} public String getAccessTokenCiphertext(){return accessTokenCiphertext;} }
